set -u; D=~/.cache/g298-dav-capture; rm -rf "$D"; mkdir -p "$D/cfg"; cd "$D"
echo '' | base64 -d | gunzip > responder.py
shasum -a 256 responder.py | cut -c1-16
echo "== svn: $(command -v svn) $(svn --version --quiet) svnrdump $(svnrdump --version --quiet) $(uname -sm) $(date -u +%Y-%m-%dT%H:%M:%SZ)"
python3 responder.py "$D/capture.jsonl" "$D/port" > "$D/responder.log" 2>&1 &
RP=$!
for i in $(seq 1 50); do [ -s "$D/port" ] && break; sleep 0.1; done
PORT=$(cat "$D/port"); U="http://127.0.0.1:$PORT/repo"
SVN="svn --non-interactive --no-auth-cache --config-dir $D/cfg --config-option servers:global:http-timeout=10"
run() { echo "## $*" | sed "s#$D#D#g; s#$PORT#PORT#g"; "$@" > "$D/out.txt" 2>&1; echo "exit $?"; tail -3 "$D/out.txt" | sed "s#$D#D#g; s#$PORT#PORT#g"; echo "@@@"; }
run $SVN lock -m "editing it" "$U/trunk/f.txt"
run $SVN lock --force -m 'x < y & "z"' "$U/trunk/f.txt"
run $SVN unlock "$U/trunk/f.txt"
run $SVN unlock --force "$U/trunk/f.txt"
run $SVN info "$U/trunk/f.txt"
run svnrdump dump --non-interactive --no-auth-cache --config-dir $D/cfg -r 1 "$U"
kill $RP; wait $RP 2>/dev/null
echo "== CAPTURE"
python3 -c 'import json,sys,base64
for r in map(json.loads, open(sys.argv[1])):
    body = base64.b64decode(r["body"]).decode("utf-8","replace")
    if r["method"] in ("LOCK","UNLOCK") or (r["method"]=="PROPFIND" and "lockdiscovery" in body) or (r["method"]=="REPORT" and "replay-report" in body):
        print(json.dumps(r))' "$D/capture.jsonl"
cd ~ && rm -rf "$D"
